#!/usr/bin/env python3
"""Strict aggregate of VBlank edges generated by interpreted CPU cycles.

This report can be published only when the pinned runtime reports the
exact 1/0/1/0 adjacent DMA-phase gaps and real psxRcntUpdate callbacks.
Original private v82 evidence is checked before and after the process.
"""
import argparse
import json
import re
from pathlib import Path
from .verify_map02_v82_native_trace import Refused

PATTERN=re.compile(
    r"^VH126_GENUINE_VBLANK_DMA_PASS stages=(\d+) dma=(\d+) "
    r"nodes=(\d+) words=(\d+) unai=(\d+) intermediate=(\d+) "
    r"adjacent_gaps=(\d+),(\d+),(\d+),(\d+) "
    r"real_vblanks=(\d+) four_back_gap2=(\d+) erased=(\d+)$",
    re.MULTILINE,
)
KEYS=("mips_stages","gpu_dma2_linked_list_transfers",
      "native_gpu_chain_nodes_visited","gpu_command_words",
      "native_unai_draw_callbacks","ordered_intermediate_vram_checks",
      "gap_A_B","gap_B_C","gap_C_D","gap_D_A",
      "real_emulator_vblank_callbacks","native_four_back_return_in_gap2",
      "previous_sample_values_erased")
EXPECTED=(4,3,10,15,5,5,1,0,1,0,2,1,1)


def summarize(log:str):
    matches=PATTERN.findall(log)
    if len(matches)!=1:
        raise Refused("missing, duplicate or truncated real-VBlank MIPS DMA witness")
    nums=tuple(int(x) for x in matches[0])
    if nums!=EXPECTED or re.search(r"^VH126_[A-Z0-9_]*REFUSED",log,re.MULTILINE):
        raise Refused("native linked-list/VBlank/pixel equality witness failed")
    return {
        "scope":"pinned_pcsx_synthetic_mips_gpu_dma_two_genuine_vblank_edges",
        **dict(zip(KEYS,nums)),
        "sampled_vram_transition_gaps":[1,0,1,0],
        "native_v119_five_handler_return_gap":2,
        "vblank_source":"actual_psxRcntUpdate_GPU_vBlank_1_0",
        "vblank_time_advanced_only_by_interpreted_mips_nop_loop":True,
        "no_host_forged_cycle_interrupt_or_vblank":True,
        "variable_mips_gpu_dma_addresses_and_packet_lengths_preserved":True,
        "five_intermediate_4x4_pixels_checked_inside_native_unai":True,
        "original_v82_private_journal_sha256_checked_by_workflow":True,
        "gpu_packets_raw_pixels_or_hashes_exported":False,
        "observed_vblank_edges_not_hardware_gpu_completion":True,
        "original_retail_MAP02_verified":False,
        "physical_PS1_verified":False,
        "HD_replacement_approved":False,
    }


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("private_runtime_log",type=Path)
    args=parser.parse_args()
    try:
        result=summarize(args.private_runtime_log.read_text())
    except (OSError,UnicodeError,Refused) as exc:
        parser.exit(2,f"REFUSED: {exc}\n")
    print(json.dumps(result,sort_keys=True))

if __name__=="__main__":
    main()
